// src/jsx/GroupChat.jsx
import { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import {
  collection,
  addDoc,
  serverTimestamp,
  query,
  onSnapshot,
  orderBy,
  doc,
  getDoc,
  setDoc
} from "firebase/firestore";

import { uploadMessageMedia } from "../js/supabaseUpload";
import useSearchUsers from "../hooks/useSearchUsers";
import Avatar from "./Avatar";

// -----------------------------------------------------
// Formatadores
// -----------------------------------------------------
function formatTime(ts) {
  if (!ts) return "";
  const d = ts?.toDate ? ts.toDate() : new Date(ts);
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function formatDay(ts) {
  if (!ts) return "";
  const d = ts?.toDate ? ts.toDate() : new Date(ts);

  const today = new Date();
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);

  if (d.toDateString() === today.toDateString()) return "Hoje";
  if (d.toDateString() === yesterday.toDateString()) return "Ontem";
  return d.toLocaleDateString();
}

export default function GroupChat({ group, currentUser, onClose }) {
  const { allUsers } = useSearchUsers();
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const listRef = useRef(null);

  // -----------------------------------------------------
  // Verificar se o usuário é membro
  // -----------------------------------------------------
  useEffect(() => {
    const members = group.members || [];
    const isMember =
      members.includes(currentUser.uid) ||
      members.some(m => m.id === currentUser.uid);

    if (!isMember) {
      alert("Você não pertence a este grupo!");
      onClose();
    }
  }, [group, currentUser.uid]);

  // -----------------------------------------------------
  // Carregar mensagens do grupo
  // -----------------------------------------------------
  useEffect(() => {
    const ref = collection(db, `groups/${group.id}/messages`);
    const q = query(ref, orderBy("createdAt", "asc"));

    const unsub = onSnapshot(q, snap => {
      const arr = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setMessages(arr);

      setTimeout(() => {
        if (listRef.current)
          listRef.current.scrollTop = listRef.current.scrollHeight;
      }, 50);
    });

    return () => unsub();
  }, [group.id]);

  // -----------------------------------------------------
  // Seleção de arquivo
  // -----------------------------------------------------
  const onSelectFile = e => {
    const f = e.target.files[0];
    if (!f) return;

    if (f.size > 40 * 1024 * 1024) {
      alert("Arquivo muito grande! Máx: 40MB");
      return;
    }

    setFile(f);
    setPreviewUrl(URL.createObjectURL(f));
  };

  // -----------------------------------------------------
  // Enviar mensagem
  // -----------------------------------------------------
  const send = async () => {
    if (!text.trim() && !file) return;

    setUploading(true);

    try {
      let type = "text";
      let url = "";

      if (file) {
        const up = await uploadMessageMedia(file, `group_${group.id}`);
        url = up.publicUrl;

        const mime = file.type.toLowerCase();
        if (mime.startsWith("image/")) type = "image";
        else if (mime.startsWith("video/")) type = "video";
        else type = "file";
      }

      await addDoc(collection(db, `groups/${group.id}/messages`), {
        text: text.trim(),
        type,
        url,
        from: currentUser.uid,
        createdAt: serverTimestamp()
      });

      await setDoc(
        doc(db, "groups", group.id),
        {
          lastUpdated: serverTimestamp(),
          lastMessage:
            type === "text"
              ? text.trim()
              : type === "image"
              ? "[imagem]"
              : type === "video"
              ? "[vídeo]"
              : "[arquivo]"
        },
        { merge: true }
      );

      setText("");
      setFile(null);
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl("");
      }
    } catch (err) {
      console.error("Erro ao enviar mensagem:", err);
      alert("Erro ao enviar mensagem.");
    }

    setUploading(false);
  };

  const findUser = id => allUsers.find(u => u.id === id);

  let lastDay = "";

  return (
    <>
      {/* HEADER */}
      <div className="chat-header">
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <button
            onClick={onClose}
            style={{
              background: "transparent",
              border: "none",
              color: "white",
              fontSize: 20,
              cursor: "pointer"
            }}
          >
            ←
          </button>

          <Avatar label={group.name} size={44} user={null} />

          <div>
            <div style={{ fontWeight: 700 }}>{group.name}</div>
            <div style={{ fontSize: 12, opacity: 0.9 }}>
              {group.members?.length || 0} membros
            </div>
          </div>
        </div>
      </div>

      {/* MENSAGENS */}
      <div className="chat-box" ref={listRef}>
        {messages.map(m => {
          const d = formatDay(m.createdAt);
          const showDay = d !== lastDay;
          lastDay = d;

          const isMe = m.from === currentUser.uid;
          const sender = findUser(m.from);

          return (
            <div key={m.id}>
              {showDay && (
                <div
                  style={{
                    textAlign: "center",
                    margin: "12px 0",
                    fontSize: 12,
                    color: "#555"
                  }}
                >
                  {d}
                </div>
              )}

              <div
                style={{
                  display: "flex",
                  alignItems: "flex-end",
                  marginBottom: 8,
                  justifyContent: isMe ? "flex-end" : "flex-start"
                }}
              >
                {!isMe && (
                  <div style={{ marginRight: 8 }}>
                    <Avatar user={sender} size={36} />
                  </div>
                )}

                <div style={{ maxWidth: "75%" }}>
                  <div className={`msg ${isMe ? "me" : "other"}`}>
                    {!isMe && (
                      <div
                        style={{
                          fontWeight: 700,
                          fontSize: 12,
                          marginBottom: 6
                        }}
                      >
                        {sender?.nome || sender?.email || "Usuário"}
                      </div>
                    )}

                    {m.type === "image" ? (
                      <img
                        src={m.url}
                        alt="img"
                        style={{ maxWidth: "100%", borderRadius: 8 }}
                      />
                    ) : m.type === "video" ? (
                      <video
                        src={m.url}
                        controls
                        style={{ maxWidth: "100%", borderRadius: 8 }}
                      />
                    ) : (
                      <div style={{ whiteSpace: "pre-wrap" }}>{m.text}</div>
                    )}
                  </div>

                  <div
                    className="hora"
                    style={{ textAlign: isMe ? "right" : "left" }}
                  >
                    {formatTime(m.createdAt)}
                  </div>
                </div>

                {isMe && <div style={{ width: 36, marginLeft: 8 }} />}
              </div>
            </div>
          );
        })}
      </div>

      {/* INPUT */}
      <div className="chat-input" style={{ flexDirection: "column", gap: 8 }}>
        {previewUrl && (
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            {file.type.startsWith("image/") && (
              <img
                src={previewUrl}
                style={{
                  width: 120,
                  height: 80,
                  borderRadius: 8,
                  objectFit: "cover"
                }}
              />
            )}

            {file.type.startsWith("video/") && (
              <video
                src={previewUrl}
                controls
                style={{ width: 160, height: 100, borderRadius: 8 }}
              />
            )}

            <div>
              <div style={{ fontWeight: 700, fontSize: 13 }}>{file.name}</div>
              <div style={{ fontSize: 12, color: "#666" }}>
                {(file.size / 1024 / 1024).toFixed(2)} MB
              </div>
            </div>

            <button
              onClick={() => {
                setFile(null);
                URL.revokeObjectURL(previewUrl);
                setPreviewUrl("");
              }}
              style={{ marginLeft: "auto" }}
            >
              Remover
            </button>
          </div>
        )}

        <div style={{ display: "flex", gap: 10 }}>
          <input
            value={text}
            onChange={e => setText(e.target.value)}
            placeholder="Mensagem..."
            style={{
              flex: 1,
              padding: 12,
              borderRadius: 25,
              border: "1px solid #ccc"
            }}
          />

          <label
            style={{
              padding: "10px 14px",
              background: "#fff",
              borderRadius: 25,
              border: "1px solid #ccc",
              cursor: "pointer"
            }}
          >
            📎
            <input
              type="file"
              accept="image/*,video/*"
              style={{ display: "none" }}
              onChange={onSelectFile}
            />
          </label>

          <button
            onClick={send}
            disabled={uploading}
            style={{
              padding: "10px 20px",
              background: "#075E54",
              color: "#fff",
              borderRadius: 25,
              border: "none",
              cursor: "pointer"
            }}
          >
            {uploading ? "Enviando..." : "Enviar"}
          </button>
        </div>
      </div>
    </>
  );
}
